CREATE OR REPLACE  VIEW ST_INGREDIENTSVENTEPOS_PRIX ("ID", "LIBELLE", "SEUIL", "UNITE", "QUANTITEPARPACK", "PU", "ACTIF", "PHOTO", "CALORIE", "DURRE", "COMPOSE", "CATEGORIEINGREDIENT", "IDFOURNISSEUR", "DATY", "QTELIMITE", "PV", "LIBELLEVENTE", "SEUILMIN", "SEUILMAX", "PUACHATUSD", "PUACHATEURO", "PUACHATAUTREDEVISE", "PUVENTEEURO", "PUVENTEUSD", "PUVENTEAUTREDEVISE", "ISVENTE", "ISACHAT", "COMPTE_VENTE", "COMPTE_ACHAT", "TVA", "TAUX", "COMPTE", "LIBELLECOMPOSANT", "TAILLE", "CODEBARRE", "REFERENCE", "CODEGROS", "PVGROS", "UNITELIB", "DESIGNATION", "COULEUR") AS
select id, LIBELLE, SEUIL, UNITE, QUANTITEPARPACK, pu, ACTIF, photo, CALORIE, DURRE, COMPOSE, CATEGORIEINGREDIENT, IDFOURNISSEUR, daty, QTELIMITE, cast(PRIXUNITAIRE as number(32,2)) as pv,
       LIBELLEVENTE, SEUILMIN, SEUILMAX, PUACHATUSD, PUACHATEURO,PUACHATAUTREDEVISE,PUVENTEEURO, PUVENTEUSD, PUVENTEAUTREDEVISE, ISVENTE,ISACHAT,COMPTE_VENTE,COMPTE_ACHAT,TVA, 1 as taux,
       COMPTE_VENTE as compte, LIBELLE as libellecomposant, '' as taille, '' as codebarre, '' as reference,'' as codegros, 1.5 as pvgros, UNITE as unitelib, LIBELLE as designation, '' as couleur
from AS_INGREDIENT_VENTE_LIB_PRX where IDTYPECLIENT='TYPE001' and (daty+0) <= SYSDATE and rownum = 1 ORDER BY daty desc;